    "import type { ExpoConfig } from 'expo/config';\n\n/**\n * The Gallery Preview harness serves this exported build under a\n * `/gallery-apps/<id>/preview` path prefix. Expo needs to know that prefix at\n * build time so every emitted asset URL resolves once the static server strips\n * it back off. We read it from the environment and normalise away any trailing\n * slash; an empty value means \"served from the web root\" (local `expo start`).\n */\nconst rawBase = process.env.GALLERY_PREVIEW_BASE ?? '';\nconst baseUrl = rawBase.replace(/\\/+$/, '');\n\nconst config: ExpoConfig = {\n  name: 'Field Service Inspector',\n  slug: 'field-service-inspector',\n  version: '1.0.0',\n  orientation: 'portrait',\n  scheme: 'fieldserviceinspector',\n  userInterfaceStyle: 'light',\n  icon: undefined,\n  splash: undefined,\n  assetBundlePatterns: ['**/*'],\n  web: {\n    bundler: 'metro',\n    output: 'single',\n  },\n  experiments: {\n    baseUrl,\n  },\n};\n\nexport default config;\n",
