    'App.tsx',
    "import { useEffect, useState } from 'react';\nimport {\n  ActivityIndicator,\n  Platform,\n  SafeAreaView,\n  ScrollView,\n  StatusBar,\n  StyleSheet,\n  Text,\n  useWindowDimensions,\n  View,\n} from 'react-native';\n\nimport { JobDetail } from './src/components/JobDetail';\nimport { JobList } from './src/components/JobList';\nimport { AppButton } from './src/components/Pressable';\nimport { SyncBar } from './src/components/SyncBar';\nimport { theme } from './src/theme';\nimport { useInspectionStore } from './src/sync/useInspectionStore';\n\nfunction Header() {\n  return (\n    <View style={styles.header}>\n      <View style={styles.brandMark}>\n        <Text style={styles.brandMarkText}>FS</Text>\n      </View>\n      <View style={styles.brandText}>\n        <Text style={styles.brandTitle}>Field Service Inspector</Text>\n        <Text style={styles.brandSubtitle}>Offline-first inspections that sync when the signal returns</Text>\n      </View>\n    </View>\n  );\n}\n\nfunction AppShell() {\n  const store = useInspectionStore();\n  const { width } = useWindowDimensions();\n  const twoPane = width >= 900;\n  const [mobileView, setMobileView] = useState<'list' | 'detail'>('list');\n\n  const selectJob = (jobId: string) => {\n    store.selectJob(jobId);\n    setMobileView('detail');\n  };\n\n  if (!store.ready) {\n    return (\n      <View style={styles.loading}>\n        <ActivityIndicator color={theme.colors.safety} />\n        <Text style={styles.loadingText}>Loading today’s route…</Text>\n      </View>\n    );\n  }\n\n  return (\n    <View style={styles.shell}>\n      <View style={styles.topBar}>\n        <Header />\n        <SyncBar\n          online={store.online}\n          queued={store.queue.length}\n          message={store.syncMessage}\n          syncConfigured={store.syncConfigured}\n          onToggleOnline={store.setOnline}\n          onPush={store.pushNow}\n        />\n      </View>\n\n      {twoPane ? (\n        <View style={styles.panes}>\n          <View style={styles.sidebar}>\n            <JobList jobs={store.jobs} selectedJobId={store.selectedJobId} onSelect={store.selectJob} />\n          </View>\n          <View style={styles.detail}>\n            <JobDetail job={store.selectedJob} actions={store.actions} />\n          </View>\n        </View>\n      ) : (\n        <View style={styles.mobile}>\n          {mobileView === 'list' ? (\n            <View style={styles.mobileList}>\n              <JobList jobs={store.jobs} selectedJobId={store.selectedJobId} onSelect={selectJob} />\n            </View>\n          ) : (\n            <View style={styles.mobileDetail}>\n              <View style={styles.backBar}>\n                <AppButton\n                  label=\"Route\"\n                  icon=\"←\"\n                  variant=\"neutral\"\n                  onPress={() => setMobileView('list')}\n                  accessibilityLabel=\"Back to today’s route\"\n                />\n                <Text style={styles.backTitle} numberOfLines={1}>\n                  {store.selectedJob?.customer ?? 'Inspection'}\n                </Text>\n              </View>\n              <JobDetail job={store.selectedJob} actions={store.actions} />\n            </View>\n          )}\n        </View>\n      )}\n    </View>\n  );\n}\n\nexport default function App() {\n  // On first mount, keep the web document background in step with the shell so\n  // there is never a white flash behind the dark header on load.\n  useEffect(() => {\n    if (Platform.OS === 'web' && typeof document !== 'undefined') {\n      document.body.style.backgroundColor = theme.colors.surface;\n    }\n  }, []);\n\n  const app = (\n    <SafeAreaView style={styles.safe}>\n      <StatusBar barStyle=\"light-content\" backgroundColor={theme.colors.anthracite} />\n      {Platform.OS === 'web' ? (\n        <ScrollView contentContainerStyle={styles.webScroll}>\n          <AppShell />\n        </ScrollView>\n      ) : (\n        <AppShell />\n      )}\n    </SafeAreaView>\n  );\n\n  return Platform.OS === 'web' ? (\n    <div data-gallery-app-id=\"field-service-inspector\" style={{ display: 'contents' }}>\n      {app}\n    </div>\n  ) : (\n    app\n  );\n}\n\nconst styles = StyleSheet.create({\n  safe: {\n    flex: 1,\n    backgroundColor: theme.colors.surface,\n  },\n  webScroll: {\n    minHeight: '100%',\n  },\n  shell: {\n    flex: 1,\n    width: '100%',\n    maxWidth: 1200,\n    alignSelf: 'center',\n    gap: theme.space(3),\n    padding: theme.space(3),\n  },\n  topBar: {\n    gap: theme.space(3),\n  },\n  header: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: theme.space(3),\n  },\n  brandMark: {\n    width: 46,\n    height: 46,\n    borderRadius: theme.radius.md,\n    backgroundColor: theme.colors.safety,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  brandMarkText: {\n    color: theme.colors.ink,\n    fontWeight: '900',\n    fontSize: theme.font.title,\n  },\n  brandText: {\n    flexShrink: 1,\n  },\n  brandTitle: {\n    color: theme.colors.ink,\n    fontSize: theme.font.display,\n    fontWeight: '800',\n  },\n  brandSubtitle: {\n    color: theme.colors.inkMuted,\n    fontSize: theme.font.label,\n  },\n  panes: {\n    flex: 1,\n    flexDirection: 'row',\n    gap: theme.space(3),\n    minHeight: 520,\n  },\n  sidebar: {\n    width: 320,\n    backgroundColor: theme.colors.anthracite,\n    borderRadius: theme.radius.lg,\n    overflow: 'hidden',\n  },\n  detail: {\n    flex: 1,\n    backgroundColor: theme.colors.surface,\n    borderRadius: theme.radius.lg,\n    borderWidth: 1,\n    borderColor: theme.colors.surfaceSunken,\n    overflow: 'hidden',\n  },\n  mobile: {\n    flex: 1,\n    minHeight: 520,\n  },\n  mobileList: {\n    flex: 1,\n    backgroundColor: theme.colors.anthracite,\n    borderRadius: theme.radius.lg,\n    overflow: 'hidden',\n  },\n  mobileDetail: {\n    flex: 1,\n    backgroundColor: theme.colors.surface,\n    borderRadius: theme.radius.lg,\n    borderWidth: 1,\n    borderColor: theme.colors.surfaceSunken,\n    overflow: 'hidden',\n  },\n  backBar: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: theme.space(3),\n    padding: theme.space(3),\n    borderBottomWidth: 1,\n    borderBottomColor: theme.colors.surfaceSunken,\n  },\n  backTitle: {\n    flexShrink: 1,\n    color: theme.colors.ink,\n    fontSize: theme.font.title,\n    fontWeight: '700',\n  },\n  loading: {\n    flex: 1,\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: theme.space(2),\n    backgroundColor: theme.colors.surface,\n  },\n  loadingText: {\n    color: theme.colors.inkMuted,\n    fontSize: theme.font.body,\n  },\n});\n",
