    'src/components/SyncBar.tsx',
    "import { StyleSheet, Text, View } from 'react-native';\n\nimport { theme } from '../theme';\nimport { AppButton } from './Pressable';\n\ninterface SyncBarProps {\n  online: boolean;\n  queued: number;\n  message: string;\n  syncConfigured: boolean;\n  onToggleOnline: (next: boolean) => void;\n  onPush: () => void;\n}\n\nexport function SyncBar({ online, queued, message, syncConfigured, onToggleOnline, onPush }: SyncBarProps) {\n  return (\n    <View style={styles.bar}>\n      <View style={styles.left}>\n        <View style={[styles.dot, { backgroundColor: online ? theme.colors.online : theme.colors.offline }]} />\n        <View style={styles.status}>\n          <Text style={styles.state}>{online ? 'Online' : 'Offline'}</Text>\n          <Text style={styles.message} numberOfLines={2}>\n            {message}\n          </Text>\n        </View>\n      </View>\n\n      <View style={styles.right}>\n        {queued > 0 ? (\n          <View style={styles.badge}>\n            <Text style={styles.badgeText}>{queued}</Text>\n          </View>\n        ) : null}\n        <AppButton\n          label={online ? 'Simulate offline' : 'Simulate 4G back'}\n          icon={online ? '✈' : '📶'}\n          variant=\"neutral\"\n          onPress={() => onToggleOnline(!online)}\n          style={styles.control}\n        />\n        <AppButton\n          label=\"Sync now\"\n          icon=\"⟳\"\n          variant=\"primary\"\n          onPress={onPush}\n          style={styles.control}\n          disabled={!online || queued === 0 || !syncConfigured}\n        />\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  bar: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'space-between',\n    gap: theme.space(3),\n    flexWrap: 'wrap',\n    backgroundColor: theme.colors.anthraciteRaised,\n    borderRadius: theme.radius.lg,\n    paddingHorizontal: theme.space(4),\n    paddingVertical: theme.space(3),\n  },\n  left: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: theme.space(3),\n    flexShrink: 1,\n    flexGrow: 1,\n    flexBasis: 220,\n  },\n  dot: {\n    width: 12,\n    height: 12,\n    borderRadius: theme.radius.pill,\n  },\n  status: {\n    flexShrink: 1,\n    gap: 2,\n  },\n  state: {\n    color: theme.colors.onDark,\n    fontSize: theme.font.label,\n    fontWeight: '700',\n    letterSpacing: 0.4,\n    textTransform: 'uppercase',\n  },\n  message: {\n    color: theme.colors.onDarkMuted,\n    fontSize: theme.font.label,\n  },\n  right: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: theme.space(2),\n  },\n  badge: {\n    minWidth: 28,\n    height: 28,\n    borderRadius: theme.radius.pill,\n    backgroundColor: theme.colors.safety,\n    alignItems: 'center',\n    justifyContent: 'center',\n    paddingHorizontal: theme.space(2),\n  },\n  badgeText: {\n    color: theme.colors.ink,\n    fontWeight: '800',\n    fontSize: theme.font.label,\n  },\n  control: {\n    minHeight: 44,\n  },\n});\n",
