    'src/data/seedJobs.ts',
    "import type { ChecklistItem, Job } from '../types';\n\nfunction checklist(items: Array<[string, string, string]>): ChecklistItem[] {\n  return items.map(([id, label, guidance]) => ({\n    id,\n    label,\n    guidance,\n    result: 'pending',\n    comment: '',\n  }));\n}\n\n/**\n * A realistic day's route for a field technician. These ship inside the app so\n * the first launch works with zero network — exactly the situation the product\n * is built for. In a remixed project these would be pulled from the backend on\n * the last connection and cached locally.\n */\nexport const seedJobs: Job[] = [\n  {\n    id: 'job-4821',\n    ref: 'WO-4821',\n    customer: 'Northwind Cold Storage',\n    site: 'Bay 3 — Ammonia Plant Room',\n    address: '14 Dockside Road, Tilbury',\n    assetType: 'Industrial refrigeration compressor',\n    scheduledFor: '08:30',\n    priority: 'urgent',\n    status: 'scheduled',\n    checklist: checklist([\n      ['leak', 'Refrigerant leak test', 'Use the electronic detector at every braze joint.'],\n      ['oil', 'Compressor oil level', 'Sight glass should read between the two etched marks.'],\n      ['guard', 'Belt guard secured', 'No missing fasteners; guard cannot be moved by hand.'],\n      ['pressure', 'High/low side pressures', 'Log gauge readings in the comment field.'],\n    ]),\n    photos: [],\n    signature: null,\n    notes: '',\n    updatedAt: '2026-07-17T06:00:00.000Z',\n  },\n  {\n    id: 'job-4822',\n    ref: 'WO-4822',\n    customer: 'Harbour Point Apartments',\n    site: 'Roof — Lift Motor Room',\n    address: '2 Marine Parade, Gravesend',\n    assetType: 'Passenger lift traction unit',\n    scheduledFor: '10:15',\n    priority: 'routine',\n    status: 'scheduled',\n    checklist: checklist([\n      ['brake', 'Brake pad thickness', 'Reject below 3 mm on either shoe.'],\n      ['rope', 'Suspension rope wear', 'Check for broken strands over one lay length.'],\n      ['estop', 'Emergency stop function', 'Car must halt within the rated distance.'],\n      ['light', 'Machine room lighting', 'Confirm the inspection lamp works.'],\n    ]),\n    photos: [],\n    signature: null,\n    notes: '',\n    updatedAt: '2026-07-17T06:00:00.000Z',\n  },\n  {\n    id: 'job-4823',\n    ref: 'WO-4823',\n    customer: 'Fenwick Distribution',\n    site: 'Yard — Loading Dock 7',\n    address: '9 Wharf Estate, Purfleet',\n    assetType: 'Hydraulic dock leveller',\n    scheduledFor: '12:00',\n    priority: 'routine',\n    status: 'scheduled',\n    checklist: checklist([\n      ['cylinder', 'Hydraulic cylinder seals', 'No weeping under load at full extension.'],\n      ['lip', 'Lip hinge condition', 'Grease and check for cracking at the welds.'],\n      ['toe', 'Toe guards intact', 'Both sides present and undamaged.'],\n      ['control', 'Hold-to-run control', 'Platform must stop the instant the button is released.'],\n    ]),\n    photos: [],\n    signature: null,\n    notes: '',\n    updatedAt: '2026-07-17T06:00:00.000Z',\n  },\n  {\n    id: 'job-4824',\n    ref: 'WO-4824',\n    customer: 'Riverside Leisure Trust',\n    site: 'Plant Room — Pool Circulation',\n    address: '1 Embankment Way, Dartford',\n    assetType: 'Pool circulation pump set',\n    scheduledFor: '14:00',\n    priority: 'urgent',\n    status: 'scheduled',\n    checklist: checklist([\n      ['seal', 'Mechanical seal drip rate', 'A slow drip is acceptable; a stream is not.'],\n      ['strainer', 'Strainer basket clear', 'Clean and reseat the lid with a good gasket.'],\n      ['dose', 'Dosing line integrity', 'No perished tubing near the injection point.'],\n      ['bond', 'Equipotential bonding', 'Verify the earth bond to the pump body.'],\n    ]),\n    photos: [],\n    signature: null,\n    notes: '',\n    updatedAt: '2026-07-17T06:00:00.000Z',\n  },\n  {\n    id: 'job-4825',\n    ref: 'WO-4825',\n    customer: 'Blackthorn Business Park',\n    site: 'Sub-station B — HVAC',\n    address: '30 Orbital Road, Thurrock',\n    assetType: 'Rooftop air handling unit',\n    scheduledFor: '15:45',\n    priority: 'routine',\n    status: 'scheduled',\n    checklist: checklist([\n      ['filter', 'Filter differential pressure', 'Replace if above the manufacturer limit.'],\n      ['belt', 'Fan belt tension', 'Around 10 mm deflection at mid-span.'],\n      ['damper', 'Fresh-air damper travel', 'Full open to full closed without binding.'],\n      ['drain', 'Condensate drain flow', 'Pour water in the tray and confirm it clears.'],\n    ]),\n    photos: [],\n    signature: null,\n    notes: '',\n    updatedAt: '2026-07-17T06:00:00.000Z',\n  },\n];\n",
